$batchPath=Join-Path $campaignPath 'hold-ownership-x10d-o-bvi-r1'
$oldPath=Join-Path $campaignPath 'hold-ownership-x10d-o-bvi'
function ReadJson($p){Get-Content -LiteralPath $p -Raw|ConvertFrom-Json}
function Bytes($p){if(Test-Path -LiteralPath $p){[long](Get-ChildItem -LiteralPath $p -File -Recurse|Measure-Object Length -Sum).Sum}else{0L}}
function Entry($p){$f=Get-Item -LiteralPath $p;@{path=$f.FullName;bytes=$f.Length;sha256=(Get-FileHash -LiteralPath $p).Hash.ToLowerInvariant()}}
function TextJson($v){($v|ConvertTo-Json -Depth 24)+"`n"}
function Save($name,$v){$p=Join-Path $batchPath $name;if(Test-Path -LiteralPath $p){throw "exists: $p"};[IO.File]::WriteAllText($p,(TextJson $v),[Text.UTF8Encoding]::new($false))}
$pre=ReadJson "$batchPath/pre-execution-binding.json";$controller=ReadJson "$oldPath/controller-review/controller-receipt.json"
if($Phase -eq 'Prepare'){
 foreach($f in @($pre.source)+@($pre.inputs)+@($pre.source_copy)+@($pre.dependencies_before)){$a=Entry $f.path;if($a.sha256 -ne $f.sha256 -or $a.bytes -ne $f.bytes){throw 'frozen binding mismatch'}}
 $natural=ReadJson "$batchPath/control-natural-exit.json";$nonzero=ReadJson "$batchPath/control-nonzero-exit.json"
 $memberDeps=@();foreach($r in @($natural,$nonzero)){foreach($m in $r.snapshots[0].members){$a=Entry $m.image;$a.mode='observed root executable fingerprint; not assembly/system closure';$memberDeps+=,$a}}
 Save 'input-manifest.json' @{schema=1;inputs=$pre.inputs;original_oracle_unchanged=$true;original_cases=69;original_supplemental=22;r1_cases=20;schema_controls=4;coverage_rows=1128;provenance_diff=(Entry "$batchPath/typed-provenance-diff.json");executed=$false}
